/**
 * Lap telemetry snapshot (`src/data/telemetry/<year>/<sessionKey>.json`, schema `apex-f1/lap-telemetry@1`), generated by
 * tools/openf1-telemetry/export.mjs from OpenF1. Everything in it is SOURCE data as published; distance, deltas and interpolated values are
 * derived in lib/telemetry/analysis.ts.
 */
export interface LapTelemetry {
  driverNumber: number;
  acronym: string | null;
  fullName: string | null;
  team: string | null;
  teamColour: string | null;
  lapNumber: number;
  /** Lap time (s) as published. */
  lapDuration: number;
  sectors: [number | null, number | null, number | null];
  /** Car samples (about 4 Hz). `t` is milliseconds from the lap's start (negative = just before the line). */
  car: { t: number[]; speed: (number | null)[]; throttle: (number | null)[]; brake: (number | null)[]; rpm: (number | null)[]; gear: (number | null)[] };
  /** Position samples in OpenF1 location units; `t` as above. */
  position: { t: number[]; x: number[]; y: number[] };
}

export interface SessionTelemetry {
  season: number;
  meetingKey: number;
  sessionKey: number;
  sessionName: string;
  eventName: string;
  circuitShortName: string | null;
  date: string;
  coordinateSystem: string;
  lapSelection: string;
  source: { name: string; url: string; fetchedOn: string; note: string };
  laps: LapTelemetry[];
  excluded: { driverNumber: number; lapNumber: number; lapDuration: number; reason: string }[];
}

export interface SessionIndexEntry {
  sessionKey: number;
  meetingKey: number;
  sessionName: string;
  eventName: string;
  circuitShortName: string | null;
  date: string;
  drivers: number;
  /** Drivers with a lap in the session (lets pages pick a session that contains a driver without opening every file). */
  acronyms?: string[];
}
